S = "Hakeem Force Academy"
QS = [
(S, "A train covers 120 km in 1 hour 40 minutes. How much distance will it cover in 15 minutes?", ["15 km", "18 km", "20 km", "30 km"], 1, "1 hour 40 minutes is 100 minutes, so the speed is 120 / 100 = 1.2 km per minute. In 15 minutes the train covers 1.2 x 15 = 18 km.", "At this speed the train runs at 72 km/h.", [1651]),
(S, "A train covers 120 km in one hour. How much distance will it cover in 12 minutes?", ["20 km", "22 km", "24 km", "30 km"], 2, "12 minutes is 1/5 of an hour. So the distance is 120 / 5 = 24 km.", "Speed in km per minute is distance in km/h divided by 60, here 2 km per minute.", [1652]),
(S, "A train covers 90 km in 1 hour. How much time will it take to cover 120 km?", ["1 hour 10 minutes", "1 hour 15 minutes", "1 hour 30 minutes", "1 hour 20 minutes"], 3, "Time = distance / speed = 120 / 90 = 4/3 hours. 4/3 hours is 1 hour 20 minutes.", "The same train covers 1.5 km every minute.", [1654]),
(S, "If a car covers 20 km in an hour, what distance does it cover in 30 minutes?", ["5 km", "15 km", "10 km", "40 km"], 2, "30 minutes is half an hour. So the distance is 20 / 2 = 10 km.", "Distance equals speed multiplied by time.", [2337]),
(S, "If a car covers 90 km in one hour and 40 minutes, in how many minutes will it cover 1 km?", ["10/9 minutes (about 1.11 minutes)", "9/10 minute", "1 minute", "2 minutes"], 0, "1 hour 40 minutes is 100 minutes for 90 km. So 1 km takes 100 / 90 = 10/9 minutes.", "The car's speed is 54 km/h.", [2339]),
(S, "Which country developed the Sinopharm vaccine against Covid-19?", ["Russia", "China", "United States", "United Kingdom"], 1, "Sinopharm is a state-owned Chinese pharmaceutical company, and its BBIBP-CorV vaccine was developed in China.", "Pakistan used the Chinese Sinopharm and CanSino vaccines in its Covid-19 vaccination drive.", [4540]),
(S, "In which year was the China-Pakistan Economic Corridor (CPEC) agreement signed and launched?", ["2013", "2014", "2016", "2015"], 3, "CPEC was launched in April 2015 when Chinese President Xi Jinping visited Pakistan and agreements worth about 46 billion dollars were signed.", "A preliminary MoU on the corridor had been signed in 2013 during the visit of Premier Li Keqiang, which is why some sources give 2013.", [257, 2723, 4203, 4204]),
(S, "Who was the first Pakistani woman cricketer to take 100 wickets in One Day Internationals?", ["Sana Mir", "Nida Dar", "Bismah Maroof", "Sadia Yousuf"], 0, "Sana Mir reached 100 ODI wickets in February 2017, the first Pakistani woman to do so. She finished as Pakistan's highest wicket-taker in women's ODIs with about 150 wickets.", "Sana Mir was inducted into the ICC Hall of Fame as Pakistan's first woman.", [4581, 4801, 4802, 5356]),
(S, "Which of the following British reforms introduced separate electorates for the Muslims of the subcontinent?", ["Cripps Mission", "Nehru Report", "Minto-Morley Reforms", "Montagu-Chelmsford Reforms"], 2, "The Indian Councils Act of 1909, known as the Minto-Morley Reforms, granted Muslims separate electorates, which was a key demand of the Simla Deputation of 1906.", "The Nehru Report of 1928 rejected separate electorates, while the Cripps Mission came in 1942.", [4577]),
(S, "Which is the major rabi (winter) crop of Pakistan?", ["Cotton", "Rice", "Wheat", "Sugarcane"], 2, "Wheat is sown in October to December and harvested in April to May, which makes it the main rabi crop.", "Cotton, rice and sugarcane are kharif (summer) crops.", [3732]),
(S, "Which crop is grown on the largest area in Pakistan?", ["Cotton", "Rice", "Maize", "Wheat"], 3, "Wheat is the staple food and covers the largest cropped area, about 9 million hectares.", "Cotton is the major cash crop of Pakistan, but it is grown on a smaller area than wheat.", [437]),
(S, "On which date is World Red Cross and Red Crescent Day celebrated?", ["8 May", "8 March", "24 October", "1 December"], 0, "It is observed on 8 May, the birthday of Henry Dunant, the founder of the Red Cross.", "Henry Dunant won the first Nobel Peace Prize in 1901.", [1525]),
(S, "What is the meaning of the word crude?", ["Polished and refined", "Natural, raw or unrefined", "Very expensive", "Quiet and gentle"], 1, "Crude means in a natural or raw state, not yet processed, or rough and lacking refinement.", "Crude oil is petroleum before it is refined into petrol and diesel.", [3211, 1138]),
(S, "What is the opposite of the word crude?", ["Raw", "Rough", "Natural", "Refined"], 3, "Crude means raw or unrefined, so its opposite is refined, meaning processed or polished.", "In manners, the opposite of crude is cultured or polite.", [1157]),
(S, "After the 2026 tournament, which country or countries will host the next FIFA World Cup in 2030?", ["Spain, Portugal and Morocco", "Qatar", "Germany", "Brazil"], 0, "FIFA awarded the 2030 World Cup to Spain, Portugal and Morocco, with opening matches in Uruguay, Argentina and Paraguay to mark the centenary.", "The 2026 World Cup was hosted jointly by the United States, Canada and Mexico, and Qatar hosted in 2022.", [4402]),
(S, "What is the currency of Belgium (Brussels) and Finland?", ["Krone", "Euro", "Pound", "Franc"], 1, "Both Belgium and Finland are members of the Eurozone and use the euro.", "Belgium used the Belgian franc before adopting the euro in 2002.", [3562]),
(S, "What is the currency of Uganda?", ["Ugandan shilling", "Kwacha", "Rand", "Birr"], 0, "Uganda's national currency is the Ugandan shilling.", "The capital of Uganda is Kampala.", [3565]),
(S, "Which is the most traded currency in the world?", ["Euro", "Japanese yen", "British pound", "US dollar"], 3, "The US dollar is on one side of the majority of global foreign exchange trades and is the main reserve currency.", "The euro is the second most traded currency.", [3801]),
(S, "What is the name of China's currency?", ["Yen", "Won", "Yuan (Renminbi)", "Ringgit"], 2, "China's official currency is the renminbi, whose main unit is the yuan.", "The word renminbi means the people's currency.", [3804]),
(S, "Who is the current Director General of the Intelligence Bureau (IB) of Pakistan?", ["Fuad Asadullah Khan", "Lt Gen Asim Malik", "Aftab Sultan", "Shahid Khaqan"], 0, "Fuad Asadullah Khan has led the IB since 2022 and in May 2026 the Prime Minister approved a four-year extension for him.", "He was the first officer from the intelligence cadre to head the IB.", [5129]),
(S, "Who is the current Chancellor of Germany?", ["Olaf Scholz", "Angela Merkel", "Friedrich Merz", "Robert Habeck"], 2, "Friedrich Merz of the CDU became Chancellor in May 2025 and was still in office in October 2026.", "His predecessor was Olaf Scholz (2021 to 2025), and before him Angela Merkel served from 2005 to 2021.", [5131]),
(S, "Who is the current Prime Minister of India?", ["Narendra Modi", "Manmohan Singh", "Rahul Gandhi", "Amit Shah"], 0, "Narendra Modi has been Prime Minister since 2014 and began his third consecutive term in June 2024.", "He is the longest-serving Prime Minister of India after Jawaharlal Nehru and Indira Gandhi in total years.", [678]),
(S, "Who is the current President of India?", ["Pratibha Patil", "Ram Nath Kovind", "Pranab Mukherjee", "Droupadi Murmu"], 3, "Droupadi Murmu took oath as the 15th President of India on 25 July 2022.", "Her predecessor Ram Nath Kovind, the answer given in 2022, served from 2017 to 2022.", [155]),
(S, "Who is the current President of the United States?", ["Joe Biden", "Donald Trump", "Barack Obama", "Kamala Harris"], 1, "Donald Trump began his second term as the 47th President on 20 January 2025.", "Joe Biden, the answer in 2022, was the 46th President from 2021 to 2025.", [1418]),
(S, "If a circle is divided into 360 equal parts, what is each part called?", ["One radian", "One degree", "One minute", "One quadrant"], 1, "A full circle measures 360 degrees, so each of 360 equal parts is one degree.", "A quadrant is a quarter of a circle, or 90 degrees.", [2343]),
(S, "Which country announced the cutting of funding to the World Health Organization in 2020 and later withdrew from it?", ["China", "United Kingdom", "India", "United States"], 3, "In 2020 President Trump halted US funding to the WHO, and in 2025 the United States started its withdrawal.", "The United States had been the largest single donor to the WHO.", [4495]),
(S, "In which country is the Khanpur (Kahnpur) Dam located?", ["Pakistan", "India", "Afghanistan", "Iran"], 0, "Khanpur Dam is on the Haro River near Haripur in Khyber Pakhtunkhwa, Pakistan.", "It supplies drinking water to Islamabad and Rawalpindi.", [2566]),
(S, "India built the Baglihar Dam on which river?", ["Jhelum", "Chenab", "Ravi", "Sutlej"], 1, "The Baglihar hydroelectric project is on the Chenab River in Jammu and Kashmir.", "Pakistan raised objections under the Indus Waters Treaty and a neutral expert gave a decision in 2007.", [1519, 2918]),
(S, "What is the name of the angel in charge of Hell (Jahannam)?", ["Israfil", "Mikail", "Malik", "Ridwan"], 2, "The Quran (Surah Az-Zukhruf) mentions Malik as the keeper of Hell.", "Ridwan is the angel who is the keeper of Paradise.", [3567, 3817]),
(S, "Hazrat Asma (R.A), known as Dhat un-Nitaqayn, was the daughter of which Sahabi?", ["Hazrat Umar (R.A)", "Hazrat Abu Bakr (R.A)", "Hazrat Ali (R.A)", "Hazrat Uthman (R.A)"], 1, "Asma bint Abu Bakr was the elder sister of Hazrat Aisha (R.A) and helped the Prophet (PBUH) during the Hijrah.", "She was the mother of Abdullah ibn Zubair (R.A).", [2073]),
(S, "Hazrat Umm Kulthum (R.A), who was married to Hazrat Uthman (R.A), was the daughter of whom?", ["Hazrat Abu Bakr (R.A)", "Hazrat Umar (R.A)", "Hazrat Ali (R.A)", "Prophet Muhammad (PBUH)"], 3, "Umm Kulthum was a daughter of the Prophet (PBUH) and married Hazrat Uthman after the death of her sister Ruqayyah.", "This is why Hazrat Uthman is called Dhun-Nurayn, the possessor of two lights.", [2089]),
(S, "Which of the following was a daughter of Hazrat Ali (R.A) and Hazrat Fatima (R.A)?", ["Hazrat Ruqayyah (R.A)", "Hazrat Zainab (R.A)", "Hazrat Hafsa (R.A)", "Hazrat Aisha (R.A)"], 1, "Hazrat Zainab bint Ali was a daughter of Hazrat Ali and Hazrat Fatima and sister of Hasan and Husain.", "Their other daughter was Umm Kulthum bint Ali.", [5144]),
(S, "Against whom did Nawab Siraj ud Daula fight the Battle of Plassey in 1757?", ["The Dutch East India Company", "The British East India Company", "The Mughals", "The Marathas"], 1, "The British East India Company forces under Robert Clive defeated the Nawab of Bengal at Plassey, helped by the betrayal of Mir Jafar.", "The battle marked the beginning of British rule in India.", [756, 3012]),
(S, "On which date is Pakistan Day celebrated?", ["14 August", "23 March", "11 September", "6 September"], 1, "Pakistan Day is celebrated on 23 March to mark the Lahore (Pakistan) Resolution of 1940.", "Pakistan became a republic on 23 March 1956 when its first constitution came into force.", [1072]),
(S, "How many days are there in a leap year?", ["365", "364", "367", "366"], 3, "A leap year has an extra day, 29 February, so it has 365 + 1 = 366 days.", "A leap year comes every four years, for example 2024 and 2028.", [2129]),
(S, "Who acts as the President of Pakistan in his absence?", ["Chairman of the Senate", "Prime Minister", "Chief Justice of Pakistan", "Speaker of the National Assembly"], 0, "Under Article 49 of the Constitution, the Chairman of the Senate acts as President when the office is vacant or the President is absent.", "If the Chairman is not available, the Speaker of the National Assembly acts as President.", [5032]),
(S, "At what age did Dr Abdul Qadeer Khan die?", ["78", "81", "90", "85"], 3, "Dr A. Q. Khan died on 10 October 2021. He was born in 1936, so he was 85.", "Most sources give his birth date as 1 April 1936, though some give 1935.", [4107]),
(S, "At what age did the Holy Prophet Muhammad (PBUH) pass away?", ["63 years", "60 years", "65 years", "70 years"], 0, "According to the most accepted account, the Prophet (PBUH) passed away in 11 AH at the age of 63 years.", "He is buried in Madinah in the room of Hazrat Aisha (R.A).", [4112]),
(S, "What is a decimal called in which the digits repeat again and again?", ["Terminating decimal", "Recurring decimal", "Irrational number", "Proper fraction"], 1, "A decimal in which a digit or block of digits repeats endlessly, like 0.333..., is called a recurring (repeating) decimal.", "Every recurring decimal can be written as a fraction of two integers, so it is a rational number.", [2344, 568]),
(S, "Between which two countries was the Tashkent Declaration of 1966 signed?", ["India and China", "Pakistan and Afghanistan", "Pakistan and India", "Pakistan and Soviet Union"], 2, "The Tashkent Declaration was signed by Pakistan and India to end the 1965 war.", "The Soviet Union under Premier Kosygin mediated, and Indian PM Shastri died in Tashkent right after signing.", [1828]),
(S, "On which date was the Lahore Declaration signed by the prime ministers of Pakistan and India?", ["21 February 1999", "5 February 1999", "6 January 2004", "23 March 1999"], 0, "Nawaz Sharif and Atal Bihari Vajpayee signed the Lahore Declaration on 21 February 1999 during Vajpayee's bus visit to Lahore.", "Months later the Kargil conflict broke out in 1999.", [589, 477, 4264]),
(S, "In which year did Quaid-e-Azam declare in Dhaka that Urdu would be the state language of Pakistan?", ["1947", "1948", "1952", "1956"], 1, "On 21 March 1948 at Dhaka, Quaid-e-Azam declared that Urdu alone would be the state language of Pakistan.", "Urdu was formally made the national language in the 1973 Constitution, so some sources give a different answer.", [982, 1253]),
(S, "Which languages were declared official languages in the 1956 Constitution of Pakistan?", ["Urdu and English", "Urdu and Bengali", "Urdu and Punjabi", "Bengali and English"], 1, "The 1956 Constitution made Urdu and Bengali the state languages of Pakistan.", "The Bengali language movement of 1952 forced this recognition.", [1336]),
(S, "Where is the deepest hole (borehole) drilled by humans in the world?", ["Russia", "United States", "Canada", "Norway"], 0, "The Kola Superdeep Borehole in Russia reached about 12,262 metres in 1989.", "It is deeper than the Mariana Trench is deep, which is about 10,935 metres.", [1117]),
]
